 on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u1 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أساسيات النظام المناخي والطاقة','مكونات النظام المناخي وميزانية الطاقة والتغذية الراجعة.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u2 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'الغازات الدفيئة والتأثير الإشعاعي','الغازات الدفيئة والانبعاثات والتأثير الإشعاعي.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u3 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'النمذجة المناخية والتصغير المكاني','النماذج العالمية والإقليمية والتقييم والتصغير.',3,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u4 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'السيناريوهات والمسارات المستقبلية','أطر السيناريوهات ومسارات الانبعاثات والتركيزات.',4,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u5 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'تحليل الإسقاطات وعدم اليقين','الإسقاطات المستقبلية ومجموعات النماذج ومصادر عدم اليقين.',5,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('climate-system-and-energy-balance','النظام المناخي ومكونات التوازن الطاقي','فهم مكونات النظام المناخي وتدفقات الطاقة والتغذية الراجعة والتوازن الإشعاعي.','{"blocks":[{"type":"heading","text":"ما النظام المناخي؟"},{"type":"text","text":"النظام المناخي منظومة مترابطة تتكون من الغلاف الجوي والمحيطات واليابسة والغلاف الجليدي والغلاف الحيوي. تتبادل هذه المكونات الطاقة والماء والزخم والمواد، وتعمل على مقاييس زمنية تتراوح من أيام إلى آلاف السنين."},{"type":"heading","text":"مكونات النظام المناخي"},{"type":"list","items":["الغلاف الجوي: ينقل الحرارة والرطوبة ويؤثر في الإشعاع والسحب.","الغلاف المائي: يخزن الحرارة وينقلها عبر التيارات والمزج.","الغلاف الجليدي: يعكس الإشعاع ويؤثر في مستوى البحر والعزل الحراري.","اليابسة: تتباين في السعة الحرارية والرطوبة والغطاء النباتي.","الغلاف الحيوي: يتفاعل مع الكربون والماء والطاقة عبر النظم البيئية."]},{"type":"heading","text":"ميزانية الطاقة عند قمة الغلاف الجوي"},{"type":"text","text":"توازن الطاقة العالمي يقارن الإشعاع الشمسي الممتص بالإشعاع الحراري الخارج إلى الفضاء. أي اختلال مستمر في الميزانية يؤدي إلى تغير مخزون الطاقة في النظام، ويظهر جزء كبير منه في ارتفاع المحتوى الحراري للمحيطات."},{"type":"heading","text":"ميزانية الطاقة السطحية"},{"type":"text","text":"تتبادل الأرض الطاقة عبر الإشعاع قصير وطويل الموجة، والحرارة المحسوسة، والحرارة الكامنة المرتبطة بالتبخر والتكاثف، وتدفق الحرارة داخل التربة أو الماء. تختلف مساهمة كل مسار حسب السطح والطقس والموسم."},{"type":"heading","text":"البياض والامتصاص"},{"type":"text","text":"البياض (Albedo) هو نسبة الإشعاع الشمسي المنعكس إلى الوارد. تختلف قيمته بين الثلج والسحب والمحيط والتربة والنباتات، كما يتغير مع زاوية الشمس وحالة السطح."},{"type":"heading","text":"الاحتباس الحراري الطبيعي"},{"type":"text","text":"تمتص بعض الغازات والسحب الإشعاع الأرضي طويل الموجة وتعيد إصدار الطاقة في اتجاهات مختلفة، ما يجعل سطح الأرض أدفأ مما سيكون عليه دون هذه الآلية الطبيعية. زيادة تركيز بعض الغازات تغير ميزانية الطاقة."},{"type":"heading","text":"التغذية الراجعة المناخية"},{"type":"list","items":["تغذية بخار الماء: الاحترار يزيد قدرة الهواء على حمل بخار الماء، وهو غاز دفيء.","تغذية الجليد والبياض: تراجع الثلج والجليد قد يقلل انعكاس الطاقة الشمسية.","تغذية السحب: أثرها يعتمد على الارتفاع والخصائص والوقت والموقع.","تغذية الكربون: تغير النظم البيئية والمحيطات قد يؤثر في تبادل الكربون."]},{"type":"heading","text":"التأثير والتغذية الراجعة"},{"type":"text","text":"التأثير المناخي يغير ميزانية الطاقة أو خصائص النظام، أما التغذية الراجعة فهي استجابة داخل النظام تعزز التغير الأولي أو تخففه. يجب عدم الخلط بين المصطلحين عند تفسير أسباب التغير."},{"type":"callout","text":"التوازن الطاقي لا يعني أن كل منطقة أو كل سنة لها ميزانية متساوية؛ المقصود غالباً ميزانية عالمية ومتوسطات على مدد مناسبة."},{"type":"example","text":"مثال: عند تراجع الغطاء الثلجي الربيعي، قد تنكشف أسطح أغمق تمتص طاقة شمسية أكبر. هذه استجابة تعزز الاحترار الأولي وتعرف بتغذية الجليد والبياض."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"النظام المناخي شبكة تفاعلات بين مكونات متعددة. فهم تدفقات الطاقة والتغذية الراجعة أساس تفسير التغير المناخي والنمذجة المناخية."}]}',350,45,'["تحديد مكونات النظام المناخي وتفاعلاتها","شرح ميزانية الطاقة عند قمة الغلاف الجوي والسطح","تمييز التغذية الراجعة عن التأثير المناخي"]','أساسيات النظام المناخي والطاقة'),
('greenhouse-gases-and-global-warming','الغازات الدفيئة وآليات الاحترار العالمي','شرح التأثير الإشعاعي للغازات الدفيئة ومصادرها ودور الأنشطة البشرية والاستجابات المناخية.','{"blocks":[{"type":"heading","text":"كيف تعمل الغازات الدفيئة؟"},{"type":"text","text":"تسمح مكونات الغلاف الجوي بمرور جزء كبير من الإشعاع الشمسي قصير الموجة، بينما تمتص غازات معينة أطوالاً موجية من الإشعاع الأرضي طويل الموجة وتعيد إصدارها. يؤدي تغير تراكيزها إلى تعديل تدفق الطاقة في النظام المناخي."},{"type":"heading","text":"أهم الغازات الدفيئة"},{"type":"list","items":["ثاني أكسيد الكربون CO₂: يرتبط أساساً بحرق الوقود الأحفوري وتغير استخدام الأراضي.","الميثان CH₄: من مصادره الزراعة والطاقة والنفايات والأنظمة الطبيعية.","أكسيد النيتروز N₂O: يرتبط بالأنشطة الزراعية وبعض العمليات الصناعية والطبيعية.","الغازات المفلورة: تستخدم في تطبيقات صناعية وتختلف في أعمارها وقدراتها الاحترارية.","بخار الماء: تغذية راجعة مهمة يتأثر تركيزها بدرجة الحرارة والدورة المائية."]},{"type":"heading","text":"التأثير الإشعاعي"},{"type":"text","text":"التأثير الإشعاعي مقياس لتغير ميزانية الطاقة نتيجة عامل مؤثر، ويعبر عنه عادة بوحدة واط لكل متر مربع. يجب تحديد تعريف التأثير المستخدم وسنة الأساس ومستوى التقييم عند مقارنة القيم."},{"type":"heading","text":"مصادر الانبعاثات"},{"type":"text","text":"تأتي الانبعاثات البشرية من الطاقة والنقل والصناعة والزراعة وتغير استخدام الأراضي وإدارة النفايات. تختلف مساهمة القطاعات بين البلدان والفترات، ولذلك يجب الرجوع إلى جرد انبعاثات موثق عند إجراء مقارنة كمية."},{"type":"heading","text":"الاحترار المرصود"},{"type":"text","text":"يظهر الاحترار العالمي في اتجاه ارتفاع متوسط درجة حرارة سطح الأرض، لكنه لا يعني ارتفاعاً متساوياً في كل منطقة أو فصل. تتأثر القيم الإقليمية بالتذبذب الطبيعي والدوران المحيطي والهباء الجوي والتغيرات المحلية."},{"type":"heading","text":"الهباء الجوي والتأثيرات الأخرى"},{"type":"text","text":"قد تعكس بعض جسيمات الهباء الإشعاع الشمسي أو تمتصه، كما تؤثر في خصائص السحب. يختلف تأثيرها حسب التركيب والحجم والارتفاع والموقع، وقد تكون أعمارها أقصر من أعمار كثير من الغازات الدفيئة."},{"type":"heading","text":"عمر الغاز والقدرة الاحترارية"},{"type":"text","text":"تختلف الغازات في عمر بقائها في الغلاف الجوي وامتصاصها الإشعاعي. لذلك لا تكفي مقارنة كتلة الانبعاثات وحدها؛ وتستخدم مقاييس مثل القدرة على الاحترار العالمي ضمن أفق زمني محدد مع معرفة حدودها."},{"type":"heading","text":"الأدلة المناخية"},{"type":"list","items":["قياسات تراكيز الغازات في الغلاف الجوي.","السجلات الآلية والبحرية وقياسات المحتوى الحراري للمحيطات.","تراجع الجليد وارتفاع مستوى البحر وتغيرات الأنظمة البيئية.","دراسات الإسناد التي تقارن العوامل البشرية والطبيعية."]},{"type":"callout","text":"لا تخلط بين الطقس البارد في يوم معين والاتجاه المناخي طويل الأمد؛ تقييم الاحترار يعتمد على سجلات عالمية متعددة وممتدة."},{"type":"example","text":"مثال: عند تفسير ارتفاع الحرارة عالمياً، افحص اتجاهات درجات الحرارة ومحتوى حرارة المحيطات وتركيزات الغازات والتأثيرات الطبيعية، بدلاً من الاعتماد على محطة أو موسم واحد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تغير تراكيز الغازات الدفيئة ميزانية الطاقة، وتُفهم آثاره من خلال الأدلة الرصدية والتحليل الإشعاعي ومقارنة العوامل البشرية والطبيعية."}]}',360,45,'["شرح كيفية تأثير الغازات الدفيئة في الإشعاع الأرضي","التعرف إلى أهم الغازات ومصادرها","التمييز بين التأثير الإشعاعي والاحترار المرصود"]','الغازات الدفيئة والتأثير الإشعاعي'),
('global-and-regional-climate-models','النماذج المناخية العالمية والإقليمية','مبادئ بناء النماذج المناخية والتمييز بين النماذج العالمية والإقليمية والتصغير المكاني.','{"blocks":[{"type":"heading","text":"ما النموذج المناخي؟"},{"type":"text","text":"النموذج المناخي تمثيل رياضي وحاسوبي للعمليات الفيزيائية والكيميائية والبيولوجية التي تتحكم في النظام المناخي. يحاكي تطور مكونات النظام وتفاعلاتها عبر مدد طويلة، ولا يهدف إلى تحديد حالة الطقس اليومية البعيدة بدقة حتمية."},{"type":"heading","text":"مكونات النماذج"},{"type":"list","items":["الغلاف الجوي والسحب والإشعاع والديناميكا.","المحيط والتيارات وتبادل الحرارة والرطوبة.","اليابسة والتربة والغطاء النباتي ودورة الكربون.","الجليد البحري والكتل الجليدية عند تضمينها.","التفاعلات الكيميائية والهباء الجوي في النماذج التي تمثلها."]},{"type":"heading","text":"النموذج العالمي"},{"type":"text","text":"يغطي النموذج المناخي العالمي الكرة الأرضية ويحل حركة الغلاف الجوي والمحيطات على شبكة عددية. تتطلب المحاكاة طويلة الأمد موارد حاسوبية كبيرة، وتظل بعض العمليات ممثلة بمخططات فيزيائية."},{"type":"heading","text":"النموذج الإقليمي"},{"type":"text","text":"يركز النموذج المناخي الإقليمي على نطاق جغرافي محدد، ويستخدم عادة شروطاً حدية جانبية من نموذج عالمي أو إعادة تحليل. يمكن أن يضيف تفاصيل تضاريس وسواحل أعلى دقة، لكنه يتأثر بجودة البيانات الحدية وباختيارات الفيزياء."},{"type":"heading","text":"الدقة المكانية والزمنية"},{"type":"text","text":"تعني الدقة المكانية حجم الخلية أو المسافة بين نقاط الشبكة، أما الدقة الزمنية فتتعلق بالفاصل الزمني للمخرجات أو الحساب. لا تعني زيادة الدقة وحدها تحسناً مضموناً في المهارة، خصوصاً إذا كانت البيانات أو الفيزياء أو التحقق غير كافية."},{"type":"heading","text":"التصغير الديناميكي والإحصائي"},{"type":"list","items":["التصغير الديناميكي: تشغيل نموذج إقليمي محدود المجال باستخدام شروط حدية.","التصغير الإحصائي: ربط مخرجات النماذج ببيانات محلية عبر علاقات إحصائية.","قد تستخدم الدراسات الطريقتين معاً، ويجب تقييمهما على بيانات مستقلة."]},{"type":"heading","text":"المحاكاة التاريخية والمستقبلية"},{"type":"text","text":"تستخدم المحاكاة التاريخية لتقييم قدرة النموذج على تمثيل المناخ السابق ضمن شروط وتجارب محددة. أما الإسقاطات المستقبلية فتستخدم سيناريوهات انبعاثات أو تركيزات أو مسارات اجتماعية اقتصادية، وليست تنبؤات حتمية بحدث يومي."},{"type":"heading","text":"تقييم النموذج"},{"type":"text","text":"قارن المخرجات ببيانات رصد أو إعادة تحليل مناسبة، وافحص المتوسطات والتباين والموسمية والتطرف والأنماط المكانية. ينبغي مراعاة انحياز النموذج وعدم يقين الرصد وعدم التطابق بين مقياس الشبكة والمحطة."},{"type":"callout","text":"النموذج الإقليمي لا يضيف معلومات مستقلة بالكامل إذا كانت شروطه الحدية غير مناسبة؛ كما أن التفاصيل المكانية الإضافية لا تضمن صحة كل ظاهرة محلية."},{"type":"example","text":"مثال: لدراسة الهطول في منطقة جبلية، قارن محاكاة عالمية بمحاكاة إقليمية أعلى دقة، ثم قيّم كليهما مقابل محطات موزعة على الارتفاعات والفصول قبل استخدام الإسقاطات."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"النماذج العالمية والإقليمية أدوات لفهم استجابة المناخ، وتحتاج إلى تقييم منهجي للفيزياء والدقة والحدود والبيانات قبل تفسير الإسقاطات."}]}',370,45,'["شرح مكونات النموذج المناخي المقترن","تمييز النماذج العالمية والإقليمية","تفسير الدقة المكانية والتصغير وحدود المحاكاة"]','النمذجة المناخية والتصغير المكاني'),
('climate-scenarios-and-emissions-pathways','السيناريوهات المناخية ومسارات الانبعاثات','فهم أطر السيناريوهات ومسارات التركيز والانبعاثات والتمييز بين الفرضيات والنتائج.','{"blocks":[{"type":"heading","text":"لماذا نستخدم السيناريوهات؟"},{"type":"text","text":"تصف السيناريوهات مسارات محتملة للتطور الاجتماعي والاقتصادي والطاقة واستخدام الأراضي والانبعاثات. توفر مدخلات متسقة لدراسة استجابة النظام المناخي تحت افتراضات مختلفة، ولا تمثل توقعاً مؤكداً لما سيحدث."},{"type":"heading","text":"من الانبعاثات إلى المناخ"},{"type":"text","text":"تؤثر الانبعاثات في تراكيز الغازات والهباء الجوي، ثم في التأثير الإشعاعي واستجابة النظام المناخي. تتضمن هذه السلسلة أزمنة استجابة ومصادر عدم يقين مختلفة."},{"type":"heading","text":"مسارات التركيز التمثيلية RCP"},{"type":"text","text":"استخدمت أطر RCP مسارات تمثيلية للتأثير الإشعاعي بحلول نهاية القرن، مثل RCP2.6 وRCP4.5 وRCP8.5. تشير الأرقام إلى مستوى التأثير الإشعاعي التقريبي في نهاية القرن ضمن سيناريو المسار، ولا تمثل درجات حرارة مباشرة."},{"type":"heading","text":"المسارات الاجتماعية الاقتصادية المشتركة SSP"},{"type":"text","text":"تصف SSP مسارات اجتماعية واقتصادية عالمية بديلة، مثل تحديات التنمية والاستدامة أو الاعتماد على الوقود الأحفوري. يمكن ربطها بمسارات انبعاثات وتأثير إشعاعي ضمن أطر السيناريوهات الحديثة."},{"type":"heading","text":"قراءة أسماء السيناريوهات"},{"type":"text","text":"في تسميات مثل SSP2-4.5، يشير الجزء الأول إلى المسار الاجتماعي الاقتصادي، والجزء الثاني إلى مستوى التأثير الإشعاعي التقريبي في نهاية القرن. يجب الرجوع إلى تعريف التجربة والنسخة المستخدمة عند تحليل البيانات."},{"type":"heading","text":"السيناريو ليس احتمالاً"},{"type":"text","text":"لا تعني تسمية السيناريو أنه الأكثر احتمالاً أو أنه سيقع حتماً. السيناريو شرط تحليلي: إذا تطور العالم وفق الافتراضات المحددة، فما الاستجابة المناخية التي تحاكيها النماذج؟"},{"type":"heading","text":"مقارنة السيناريوهات"},{"type":"list","items":["قارن الفترة المرجعية والفترة المستقبلية نفسها.","تحقق من مجموعة النماذج والنسخة والسيناريو.","افصل بين المتوسط متعدد النماذج ونطاق التباين بينها.","لا تخلط بين مسار انبعاثات ومسار تركيز أو تأثير إشعاعي.","وثق افتراضات استخدام الأراضي والهباء الجوي عند توفرها."]},{"type":"heading","text":"الاستخدام في التخطيط"},{"type":"text","text":"تساعد السيناريوهات على اختبار متانة الخطط أمام نطاق من الظروف المحتملة، مثل احتياجات المياه أو الحرارة أو الزراعة. الأفضل دراسة عدة سيناريوهات بدلاً من الاعتماد على مسار واحد."},{"type":"callout","text":"لا تعرض السيناريو الأعلى أو الأدنى بوصفه تنبؤاً مؤكداً؛ قدمه كمسار مشروط وافصل الافتراضات عن نتائج النموذج."},{"type":"example","text":"مثال: لتقييم احتياجات المياه، قارن تغير الهطول والحرارة والتبخر المحتمل تحت أكثر من مسار، ثم اختبر أثر النتائج على إدارة الموارد مع توضيح نطاق عدم اليقين."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"السيناريوهات أطر شرطية لاستكشاف المستقبل. فهم افتراضاتها وتسمياتها وحدودها يمنع تحويل الإسقاطات إلى تنبؤات حتمية."}]}',380,45,'["شرح وظيفة السيناريوهات المناخية","التمييز بين RCP وSSP بصورة مفاهيمية","تفسير السيناريو كفرضية شرطية لا كتنبؤ حتمي"]','السيناريوهات والمسارات المستقبلية'),
('future-climate-projections-and-uncertainty','إسقاطات المناخ المستقبلية وتقييم عدم اليقين','تحليل الإسقاطات المستقبلية ومصادر عدم اليقين ومجموعات النماذج والمهارات اللازمة لاستخدامها.','{"blocks":[{"type":"heading","text":"ما الإسقاط المناخي؟"},{"type":"text","text":"الإسقاط المناخي محاكاة شرطية لاستجابة المناخ تحت سيناريو محدد من الانبعاثات أو التركيزات والعوامل المؤثرة. يختلف عن التنبؤ الجوي التشغيلي الذي يحاول وصف تطور حالة الطقس من شروط ابتدائية محددة."},{"type":"heading","text":"مصادر عدم اليقين"},{"type":"list","items":["عدم يقين السيناريو: اختلاف المسارات المستقبلية للانبعاثات والتنمية.","عدم يقين النموذج: اختلاف تمثيل العمليات والفيزياء والحساسية المناخية.","التباين الطبيعي الداخلي: تقلبات النظام المناخي حتى مع السيناريو نفسه.","عدم يقين البيانات والرصد والتصغير والمعالجة اللاحقة."]},{"type":"heading","text":"مجموعات النماذج"},{"type":"text","text":"تستخدم مجموعات متعددة النماذج لتقدير نطاق الاستجابات المناخية. لكن أعضاء المجموعة ليسوا بالضرورة عينات مستقلة إحصائياً؛ فقد تشترك النماذج في بنى أو مكونات أو بيانات، لذلك يجب تفسير انتشارها بحذر."},{"type":"heading","text":"المتوسط والنطاق"},{"type":"text","text":"يمكن عرض متوسط المجموعة ومجال المئينات أو النطاق بين النماذج. المتوسط لا يلغي الاختلافات الإقليمية أو التباين الطبيعي، والنطاق ليس ضماناً بأنه يحتوي جميع النتائج الممكنة."},{"type":"heading","text":"الفترات الزمنية"},{"type":"text","text":"تستخدم نوافذ متعددة السنوات لتقليل أثر التذبذب السنوي عند مقارنة المناخ المستقبلي بالفترة المرجعية. يجب توضيح طول النافذة والفترة المرجعية وسيناريو الإسقاط."},{"type":"heading","text":"المتغيرات والمؤشرات"},{"type":"list","items":["متوسط الحرارة والحرارة القصوى والدنيا.","مجموع الهطول وتواتره وشدته وفترات الجفاف.","مؤشرات موجات الحر والليالي الدافئة.","مؤشرات الجفاف الزراعي والهيدرولوجي عند توفر البيانات المناسبة."]},{"type":"heading","text":"عدم اليقين الإقليمي"},{"type":"text","text":"قد تكون الثقة أعلى في اتجاه تغير الحرارة من الثقة في تغير الهطول محلياً، كما تختلف النتائج بحسب الموسم والتضاريس ومقياس الدراسة. ينبغي وصف مستوى الثقة لكل متغير ومنطقة بدلاً من إعطاء حكم عام واحد."},{"type":"heading","text":"التصغير وتصحيح الانحياز"},{"type":"text","text":"قد تستخدم بيانات مصغرة مكانياً أو مصححة إحصائياً لتناسب دراسات الأثر. يجب التحقق من حفظ الاتجاهات والتطرف والتغيرات المستقبلية، لأن بعض طرق التصحيح قد تغير خصائص التوزيع أو تقلل الاتساق الفيزيائي."},{"type":"heading","text":"عرض النتائج لصناع القرار"},{"type":"list","items":["حدد السؤال والقطاع والمنطقة والفترة.","اعرض السيناريوهات والنطاقات لا رقماً منفرداً فقط.","افصل الإشارة المناخية عن التباين الطبيعي.","وضح جودة البيانات وطرق التصغير والتصحيح.","حوّل النتائج إلى مؤشرات قابلة للاستخدام مع ذكر الحدود."]},{"type":"callout","text":"لا تفسر نطاق النماذج على أنه احتمال مباشر، ولا تستخدم إسقاطاً محلياً دون تقييم تمثيله للمناخ الحالي وملاءمته للقرار."},{"type":"example","text":"مثال: عند دراسة موجات الحر المستقبلية، قارن عدد الأيام فوق عتبة محلية في فترة مرجعية ومستقبلية عبر عدة نماذج وسيناريوهات، واعرض الوسيط والنطاق والتغير بين المواسم."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تتطلب إسقاطات المناخ قراءة شرطية تراعي السيناريو والنموذج والتباين الطبيعي وجودة التصغير. أفضل الممارسات تعرض نطاق النتائج وتشرح ما يمكن وما لا يمكن استنتاجه."}]}',390,45,'["تمييز الإسقاط المناخي عن التنبؤ الجوي","تصنيف مصادر عدم اليقين في الإسقاطات","عرض نطاق النتائج بطريقة مناسبة لدعم التخطيط"]','تحليل الإسقاطات وعدم اليقين')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'أساسيات النظام المناخي والطاقة' then u1.id when 'الغازات الدفيئة والتأثير الإشعاعي' then u2.id when 'النمذجة المناخية والتصغير المكاني' then u3.id when 'السيناريوهات والمسارات المستقبلية' then u4.id else u5.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التغير المناخي والنمذجة المناخية',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;